/*
 * gen_rhythm_rom.c — offline generator (NOT part of the build).
 *
 * Decodes the OPNA ADPCM-A rhythm ROM (file "need", 8192 bytes) into 16-bit PCM and emits
 * opna_rhythm_rom.cpp, which is compiled into the fmgen OPNA so that FMP and
 * S98 playback have working hardware-rhythm (BD/SD/TOP/HH/TOM/RIM) drums
 * without any runtime/secondary file.
 *
 * The decode is a byte-for-byte reimplementation of 98fmplayer's
 * libopna/opnadrum.c (opna_drum_set_rom): each drum's ADPCM-A stream is
 * decoded and integer-upsampled (x3 or x6) to a common 55466 Hz rate — the
 * same rate at which 98fmplayer mixes the OPNA (opna_ssg_mix_55466). fmgen's
 * OPNA::RhythmMix then resamples from that rate to the output rate.
 *
 * Regenerate with:
 *   cc -O2 gen_rhythm_rom.c -o /tmp/gen_rhythm_rom
 *   /tmp/gen_rhythm_rom need opna_rhythm_rom.cpp
 */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

/* OPNA rhythm output rate (== 98fmplayer opna_ssg_mix_55466). */
#define OPNA_RHYTHM_RATE 55466

#define ROM_SIZE 0x2000

static const uint16_t steps[49] = {
    16,  17,   19,   21,   23,   25,   28,
    31,  34,   37,   41,   45,   50,   55,
    60,  66,   73,   80,   88,   97,  107,
    118, 130,  143,  157,  173,  190,  209,
    230, 253,  279,  307,  337,  371,  408,
    449, 494,  544,  598,  658,  724,  796,
    876, 963, 1060, 1166, 1282, 1411, 1552
};
static const int8_t step_inc[8] = { -1, -1, -1, -1, 2, 5, 7, 9 };

static const struct { unsigned start, end; int div; } part[6] = {
    {0x0000, 0x01c0 - 1, 3}, /* BD  */
    {0x01c0, 0x0440 - 1, 3}, /* SD  */
    {0x0440, 0x1b80 - 1, 3}, /* TOP */
    {0x1b80, 0x1d00 - 1, 3}, /* HH  */
    {0x1d00, 0x1f80 - 1, 6}, /* TOM */
    {0x1f80, 0x2000 - 1, 6}, /* RIM */
};
static const char* names[6] = { "bd", "sd", "top", "hh", "tom", "rim" };

int main(int argc, char** argv)
{
    if (argc != 3) {
        fprintf(stderr, "usage: %s <need> <out.cpp>\n", argv[0]);
        return 2;
    }
    FILE* f = fopen(argv[1], "rb");
    if (!f) { perror("open rom"); return 1; }
    uint8_t rom[ROM_SIZE];
    if (fread(rom, 1, ROM_SIZE, f) != ROM_SIZE) {
        fprintf(stderr, "rom must be exactly %d bytes\n", ROM_SIZE);
        return 1;
    }
    fclose(f);

    /* Decode each drum into a PCM buffer. */
    int16_t* pcm[6];
    int len[6];
    for (int p = 0; p < 6; p++) {
        /* worst case: (end-start+1)*2 nibbles * div */
        int cap = (int)((part[p].end - part[p].start + 1) * 2 * part[p].div + 16);
        pcm[p] = (int16_t*)malloc(sizeof(int16_t) * cap);
        unsigned addr = part[p].start << 1;
        int step = 0;
        int acc = 0;
        int out = 0;
        for (;;) {
            if ((addr >> 1) == part[p].end) break;
            unsigned data = rom[addr >> 1];
            if (!(addr & 1)) data >>= 4;
            data &= 0x0f;
            int acc_diff = ((((data & 7) << 1) | 1) * steps[step]) >> 3;
            if (data & 8) acc_diff = -acc_diff;
            acc += acc_diff;
            step += step_inc[data & 7];
            if (step < 0) step = 0;
            if (step > 48) step = 48;
            addr++;
            int s = acc & ((1 << 12) - 1);
            if (s >= (1 << 11)) s -= (1 << 12);
            int16_t s16 = (int16_t)(s << 4);
            for (int i = 0; i < part[p].div; i++) pcm[p][out++] = s16;
        }
        len[p] = out;
    }

    FILE* o = fopen(argv[2], "w");
    if (!o) { perror("open out"); return 1; }
    fprintf(o,
        "// Auto-generated by gen_rhythm_rom.c from the OPNA ADPCM-A rhythm ROM (file \"need\").\n"
        "// Decoded 16-bit PCM for the 6 OPNA rhythm voices, native rate %d Hz.\n"
        "// Embedded into the fmgen OPNA so FMP/S98 drums play with no runtime file.\n"
        "// DO NOT EDIT BY HAND - regenerate via gen_rhythm_rom.c.\n\n",
        OPNA_RHYTHM_RATE);

    for (int p = 0; p < 6; p++) {
        fprintf(o, "static const short opna_rhythm_pcm_%s[%d] = {\n", names[p], len[p]);
        for (int i = 0; i < len[p]; i++) {
            fprintf(o, "%d,", pcm[p][i]);
            if ((i & 15) == 15) fprintf(o, "\n");
        }
        fprintf(o, "\n};\n\n");
        free(pcm[p]);
    }

    /* The OPNA class lives in namespace FM, so these externs must too. */
    fprintf(o, "namespace FM {\n");
    fprintf(o, "extern const int opna_rhythm_present = 1;\n");
    fprintf(o, "extern const int opna_rhythm_rate = %d;\n", OPNA_RHYTHM_RATE);
    fprintf(o, "extern const int opna_rhythm_len[6] = {%d,%d,%d,%d,%d,%d};\n",
            len[0], len[1], len[2], len[3], len[4], len[5]);
    fprintf(o, "extern const short* const opna_rhythm_pcm[6] = {\n"
               "    opna_rhythm_pcm_bd, opna_rhythm_pcm_sd, opna_rhythm_pcm_top,\n"
               "    opna_rhythm_pcm_hh, opna_rhythm_pcm_tom, opna_rhythm_pcm_rim\n"
               "};\n");
    fprintf(o, "} // namespace FM\n");
    fclose(o);

    fprintf(stderr, "wrote %s : lengths BD=%d SD=%d TOP=%d HH=%d TOM=%d RIM=%d\n",
            argv[2], len[0], len[1], len[2], len[3], len[4], len[5]);
    return 0;
}
